//! The committed generated files are the ones the schema produces.
//!
//! Both are generated by hand and checked in — `src/gatt.rs` by
//! `tool/gen_gatt.sh`, `calypso-app/lib/gatt/gatt_client.dart` by the app's copy
//! of the same script — so nothing else in either build would notice a schema
//! change that was never regenerated: the firmware would keep serving the old
//! table and the app would keep speaking the old interface, with no way for
//! either end to tell. These regenerate in memory and compare.
//!
//! Both checks live here because this is the crate that can run the tool: the app
//! has no Rust toolchain in `flutter test`, and a check that needs one would not
//! be run at all.

use gatt_gen::generator::client::dart_universal_ble;
use gatt_gen::generator::server::rust_trouble::{self, Config};
use gatt_gen::{Input, Target};

/// The commands the two generated files name in their own headers, so the test
/// has to name them the way the scripts name themselves.
const RUST_SCRIPT: &str = "calypso-core/tool/gen_gatt.sh";
const DART_SCRIPT: &str = "calypso-app/tool/gen_gatt.sh";

/// How many warnings this schema earns, which is a property of the sizes declared
/// in `proto/calypso_gatt.proto`: both characteristics are bigger than the 20
/// bytes every stack guarantees.
const EXPECTED_WARNINGS: usize = 2;

fn schema() -> gatt_gen::Gatt {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("the crate is in the repo root");
    let (schema, warnings) = gatt_gen::load(&Input::new([root.join("proto/calypso_gatt.proto")]))
        .expect("the schema loads and is valid");
    assert_eq!(
        warnings.len(),
        EXPECTED_WARNINGS,
        "the schema warns differently than proto/calypso_gatt.proto says: {warnings:?}"
    );
    schema
}

#[test]
fn the_committed_table_is_what_the_tool_generates() {
    let generated = rust_trouble::generate(
        &schema(),
        &Config {
            message_module: "crate::pb::msg".to_string(),
            server_name: "CalypsoGatt".to_string(),
            pipe_chunk_max: 244,
            // No pipe in this schema yet, so neither of these reaches the file;
            // they have to match what `tool/gen_gatt.sh` passes all the same.
            pipe_msg_max: 0,
            window: 8,
            xfer_timeout_ms: 5000,
            regenerate_with: Some(RUST_SCRIPT.to_string()),
        },
    )
    .expect("the schema is emittable");

    assert_eq!(generated.file_name, "gatt.rs");
    assert_eq!(
        generated.source,
        include_str!("../src/gatt.rs"),
        "src/gatt.rs is stale: run {RUST_SCRIPT}"
    );
}

#[test]
fn the_committed_client_is_what_the_tool_generates() {
    let output = Target::DartUniversalBle
        .generate(
            &schema(),
            &gatt_gen::generator::Config::DartUniversalBle(dart_universal_ble::Config {
                messages_import: "../protocol/calypso.pb.dart".to_string(),
                messages_prefix: "pb".to_string(),
                regenerate_with: Some(DART_SCRIPT.to_string()),
            }),
        )
        .expect("the schema is emittable");

    assert_eq!(output.file_name, "gatt_client.dart");
    assert_eq!(
        output.source,
        include_str!("../../calypso-app/lib/gatt/gatt_client.dart"),
        "calypso-app/lib/gatt/gatt_client.dart is stale: run {DART_SCRIPT}"
    );
}
